-- Auto-generated by rolo.pointer plugin. Do not edit by hand.
-- Profile: macos. Values: ~/.config/hypr/pointer-tuning.json (Pointer panel).
local C = dofile(os.getenv("HOME") .. "/.config/hypr/trackpad/curves.lua")
local k = C.display_k(2, 2246)

hl.config({
  input = {
    sensitivity = -0.49,
    accel_profile = "adaptive",
    scroll_factor = 1.2,
    natural_scroll = false,
  },
})

hl.device({
  name = "apple-mtp-multi-touch",
  accel_profile = C.motion_profile({ shape = "macos", tracking = 0.875, gain = k * 0.87 }),
  scroll_points = C.scroll_points({ index = 0.4412, accel = 1.0, mac_velocity = true, factor = 0.55 }),
  sensitivity = 0,
  scroll_factor = 1.0,           -- size is in scroll_points; window rules replace this per app
  natural_scroll = true,
  scroll_method = "2fg",
  clickfinger_behavior = true,
  tap_to_click = false,
  tap_button_map = "lrm",
  tap_and_drag = false,
  drag_lock = 0,
  drag_3fg = 0,
  disable_while_typing = true,
  middle_button_emulation = false,
  left_handed = false,
})

for _, name in ipairs({ "logitech-usb-receiver", "logitech-usb-receiver-keyboard-1" }) do
  hl.device({
    name = name,
    accel_profile = C.mouse_profile({ scaling = 2.0, hz = 1000, k = k, gain = 1.0 }),
    scroll_points = C.wheel_points({ scaling = 0.75, base = 4 * k * 2 / 120 * 1.0 }),
    sensitivity = 0,
    scroll_factor = 1.0,
    natural_scroll = true,
    left_handed = false,
    middle_button_emulation = false,
  })
end

-- macOS: four-finger swipes switch Spaces, four-finger pinch opens Apps.
hl.gesture({ fingers = 4, direction = "horizontal", action = "workspace" })
hl.gesture({ fingers = 4, direction = "pinchin", action = function() hl.exec_cmd("omarchy-shell omarchy.dock apps") end })

-- Same scroll distance in every toolkit, Chromium/Electron as the reference (no rule):
-- rule = reference px per unit / toolkit px per unit (macos-feel README, "Scrolling in every app").
local ref_tp, ref_wheel = 12 / 2, 120 / 2
local GTK4 = "(org\\.gnome\\.(Nautilus|Papers|TextEditor|Calculator|Loupe|Snapshot|Settings|Characters|clocks|Weather)|com\\.github\\.PintaProject\\.Pinta)"
local GTK3 = "(org\\.gnome\\.(Evince|DiskUtility)|evince|gnome-disks)"
local rules = {
  { GTK4, nil, 2.5, 1000 ^ (2 / 3) },
  { GTK3, nil, 1000 ^ (2 / 3) / 10, nil },
  { "(Alacritty)", "(Alacritty)", 3, nil },
  { "(kitty)", "(kitty)", 1, nil },
  { "foot", "foot", 7 / 2, 7 * 13 },
}
if type(o) == "table" and o.window then
  for _, r in ipairs(rules) do
    local function rule()
      return { scroll_touchpad = ref_tp / r[3], scroll_mouse = r[4] and ref_wheel / r[4] or nil }
    end
    o.window(r[1], rule())
    if r[2] then o.window({ class = "(org\\.omarchy\\..*|TUI\\..*)", initial_title = r[2] }, rule()) end
  end
end

hl.exec_cmd("hyprctl setcursor Adwaita 19")
